import math

def online_moments(values):
    n, mean, m2 = 0, 0.0, 0.0
    for value in values:
        if type(value) is not float or not math.isfinite(value):
            raise ValueError("expected finite float")
        next_n = n + 1
        delta = value - mean
        next_mean = mean + delta / next_n
        next_m2 = m2 + delta * (value - next_mean)
        if not math.isfinite(next_mean) or not math.isfinite(next_m2):
            raise ValueError("nonfinite accumulator")
        n, mean, m2 = next_n, next_mean, next_m2
    if n == 0:
        return {"count": 0, "mean": None, "population_variance": None, "sample_variance": None}
    return {"count": n, "mean": mean,
            "population_variance": m2 / n,
            "sample_variance": m2 / (n - 1) if n > 1 else None}

result = online_moments([2.0, 4.0, 6.0])
print(result["count"])
print(result["mean"])
print(result["population_variance"])
print(result["sample_variance"])
print(online_moments([])["mean"])

import math

def recursive_ema(values, alpha):
    if type(alpha) is not float or not math.isfinite(alpha) or not 0 < alpha <= 1:
        raise ValueError("alpha must be a finite float in (0, 1]")
    state = None
    path = []
    for value in values:
        if type(value) is not float or not math.isfinite(value):
            raise ValueError("expected finite float")
        state = value if state is None else (1 - alpha) * state + alpha * value
        if not math.isfinite(state):
            raise ValueError("nonfinite accumulator")
        path.append(state)
    return path

print(recursive_ema([2.0, 4.0, 6.0], 0.5))
print(recursive_ema([], 0.5))
